t-weight: 700; }\n    .session-status-complete      { color: #58a6ff; font-weight: 700; }\n    .session-status-limit_reached { color: #ff4d4f; font-weight: 700; }\n\n    /* \u2500\u2500 Tab nav \u2500\u2500 */\n    .tab-nav { display: flex; gap: 0; margin-bottom: 1.25rem; border-bottom: 1px solid #30363d; }\n    .tab-btn {\n      background: none; border: none; border-bottom: 2px solid transparent;\n      color: #8b949e; padding: 0.5rem 1.2rem; font-size: 0.85rem; cursor: pointer;\n      transition: color .15s; margin-bottom: -1px;\n    }\n    .tab-btn:hover { color: #c9d1d9; }\n    .tab-btn.active { color: #f0f6fc; border-bottom-color: #58a6ff; font-weight: 600; }\n    .tab-content { display: none; }\n    .tab-content.active { display: block; }\n\n    /* \u2500\u2500 Stats bar \u2500\u2500 */\n    #stats { display: flex; gap: 0.6rem; flex-wrap: wrap; margin-bottom: 1.25rem; }\n    .stat {\n      padding: 0.25rem 0.75rem; border-radius: 4px; font-size: 0.8rem;\n      font-weight: 600; border: 1px solid; cursor: pointer; transition: opacity .15s;\n    }\n    .stat:hover { opacity: .7; }\n    .stat.active { outline: 2px solid white; }\n    .stat-all      { background: #21262d;              border-color: #6e7681; color: #c9d1d9; }\n    .stat-critical { background: rgba(255,77,79,.15);  border-color: #ff4d4f; color: #ff4d4f; }\n    .stat-high     { background: rgba(250,140,22,.15); border-color: #fa8c16; color: #fa8c16; }\n    .stat-medium   { background: rgba(250,173,20,.15); border-color: #faad14; color: #faad14; }\n    .stat-low      { background: rgba(82,196,26,.15);  border-color: #52c41a; color: #52c41a; }\n    .stat-info     { background: rgba(24,144,255,.15); border-color: #1890ff; color: #1890ff; }\n\n    /* \u2500\u2500 Findings table \u2500\u2500 */\n    table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }\n    thead tr { background: #161b22; }\n    th { text-align: left; padding: 0.5rem 0.75rem; color: #8b949e; font-weight: 500;\n         bo